**Gates before launch.** The prediction and plan for this round are already committed, so the gates come next, in this order. First, I run the grader selftest on `spe/evals/graders/grade.py`. Three inputs go in: the oracle file built from `spe/evals/tasks/answers.json`, which must score 50 of 50 on both category and priority, then an empty-label file and a wrong-label file, which must both score 0 without crashing. The eval set held 40 tickets before this round. So I also confirm that `answers.json` now has exactly 50 entries, and I stop and ask you if it does not. Second, I regrade the saved round 3 trial outputs with this round's `grade.py` and `judge.md`. The scores must match the round 3 measured numbers in `spe/prediction-log.md`. If they differ, the grader changed. I log that in `spe/failures.md` before anything runs. Third, I do a dry run with `args.only: ['B:T001', 'C2:T001', 'C2:T027']` and `args.trials: 2`. It passes if every trial returns valid output, the grader and judge both return results, no trial is voided, and the spend log stays under $1. If any gate fails, I halt and report. Nothing launches until all three pass. When they do, I commit `spe/evals/harness/r04-workflow.js` locally and launch with the 50 ticket ids and `capUsd: 40`.

I assumed these defaults: the triage CLI runs as `npm run triage -- --config <file> --ticket <path> --json`, tickets are in `fixtures/tickets/` (outside `spe/`), configs are in `triage/configs/`, and `judge.md` scores tone on a 1 to 5 scale.

```js
export const meta = {
  name: 'triage-spe-eval',
  description: 'SPE eval for the triage agent. Configs B and C2 run on the ticket set. Labels are graded in code. Split cells get top-up trials. Reply tone is judged blind by Opus. A failure analysis and a completeness critic close the run.',
  phases: ['Trials', 'Scan', 'Grade', 'Top-up', 'Judge', 'Synthesis'],
}

// The round lives here only. Prompt text uses TAG and never a hand-typed round number.
const ROUND = 4
const TAG = `r${String(ROUND).padStart(2, '0')}`
const A = args ?? {}

// Defaults match the approved plan. Override through args.
const CONFIGS = A.configs ?? [
  { id: 'B', file: 'triage/configs/B.yaml', note: '12-line prompt, 6 tools' },
  { id: 'C2', file: 'triage/configs/C2.yaml', note: '12-line prompt, 3 tools plus check_status' },
]
const TICKETS = A.tickets ?? []                // the ticket ids, e.g. ['T001', ...]
const EXPECTED_TICKETS = A.expectedTickets ?? 50
const TICKET_DIR = A.ticketDir ?? 'fixtures/tickets'
const TRIAGE_CMD = A.triageCmd ?? 'npm run --silent triage --'
const TRIALS = A.trials ?? 5
const ONLY = A.only ?? null                    // dry run cells, e.g. ['B:T001', 'C2:T027']
const TRANSCRIPT_DIR = A.transcriptDir ?? null
const CONCURRENCY = A.concurrency ?? 20
const TONE_FAIL = A.toneFail ?? 2              // tone at or below this counts as a failure

// Caps. Each estimate is unmeasured. Spend is settled as max(estimate, reported cost).
const CAP_USD = A.capUsd ?? 40
const EST_TRIAL_USD = A.estTrialUsd ?? 0.05
const EST_GRADE_USD = A.estGradeUsd ?? 0.05
const EST_JUDGE_USD = A.estJudgeUsd ?? 0.15
const EST_AGENT_USD = A.estAgentUsd ?? 0.25    // scan, failure analysis, critic
const MAX_AGENTS = A.maxAgents ?? 800
const TOPUP_PER_CELL = A.topUpPerCell ?? 3
const TOPUP_MAX = A.topUpMax ?? 60
const GRADE_BATCH = A.gradeBatch ?? 50
const VOID_HALT_RATE = A.voidHaltRate ?? 0.1

const FORBIDDEN = 'spe/'

if (!ONLY && TICKETS.length !== EXPECTED_TICKETS) {
  throw new Error(`args.tickets has ${TICKETS.length} ids. The approved plan needs ${EXPECTED_TICKETS}.`)
}

// ---------- Budget ----------
let spent = 0
let reserved = 0
let agentsUsed = 0
const skips = []
const HOLDBACK = EST_AGENT_USD * 2             // keeps room for failure analysis and the critic

function skip(what, reason, usd) {
  skips.push({ what, reason, usd })
  log(`SKIP ${what}: ${reason}. Spent $${spent.toFixed(2)} of $${CAP_USD}. Agents ${agentsUsed} of ${MAX_AGENTS}.`)
  return false
}
function reserve(usd, what, final = false) {
  if (agentsUsed >= MAX_AGENTS) return skip(what, 'agent cap', usd)
  const room = CAP_USD - spent - reserved - (final ? 0 : HOLDBACK)
  if (usd > room) return skip(what, 'spend cap', usd)
  reserved += usd
  agentsUsed += 1
  return true
}
function settle(est, reported) {
  reserved -= est
  spent += Math.max(est, Number(reported) || 0)
}

// ---------- Helpers ----------
async function inChunks(items, fn) {
  const out = []
  for (let i = 0; i < items.length; i += CONCURRENCY) {
    const part = await parallel(items.slice(i, i + CONCURRENCY).map(x => () => fn(x)))
    out.push(...part)
  }
  return out
}
function seeded(str) {
  let h = 2166136261
  for (const ch of str) h = Math.imul(h ^ ch.charCodeAt(0), 16777619)
  return () => {
    h = Math.imul(h ^ (h >>> 15), 2246822507)
    h = Math.imul(h ^ (h >>> 13), 3266489909)
    h ^= h >>> 16
    return (h >>> 0) / 4294967296
  }
}
function shuffle(list, key) {
  const rand = seeded(key)
  const a = [...list]
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1))
    const tmp = a[i]
    a[i] = a[j]
    a[j] = tmp
  }
  return a
}
function groupBy(xs, f) {
  const m = new Map()
  for (const x of xs) {
    const k = f(x)
    if (!m.has(k)) m.set(k, [])
    m.get(k).push(x)
  }
  return m
}
const mean = xs => (xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : null)
const r3 = x => (x == null ? null : Math.round(x * 1000) / 1000)

// ---------- Cells ----------
const cells = ONLY
  ? ONLY.map(key => {
      const [cid, ticket] = key.split(':')
      const config = CONFIGS.find(c => c.id === cid)
      if (!config || !ticket) throw new Error(`Bad args.only entry: ${key}`)
      return { key, config, ticket }
    })
  : CONFIGS.flatMap(config => TICKETS.map(ticket => ({ key: `${config.id}:${ticket}`, config, ticket })))

// ---------- Schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['status', 'category', 'priority', 'reply', 'tool_calls', 'tool_errors',
    'input_tokens', 'output_tokens', 'latency_ms', 'cost_usd', 'files_read'],
  properties: {
    status: { type: 'string', enum: ['ok', 'harness_error', 'rate_limited'] },
    category: { type: ['string', 'null'] },
    priority: { type: ['string', 'null'] },
    reply: { type: ['string', 'null'] },
    tool_calls: { type: 'integer' },
    tool_errors: { type: 'integer' },
    input_tokens: { type: 'integer' },
    output_tokens: { type: 'integer' },
    latency_ms: { type: 'integer' },
    cost_usd: { type: 'number' },
    files_read: { type: 'array', items: { type: 'string' } },
    error: { type: 'string' },
  },
}
const SCAN_SCHEMA = {
  type: 'object',
  required: ['scanned', 'peeked'],
  properties: {
    scanned: { type: 'integer' },
    peeked: { type: 'array', items: { type: 'object', required: ['id', 'evidence'],
      properties: { id: { type: 'string' }, evidence: { type: 'string' } } } },
  },
}
const GRADE_SCHEMA = {
  type: 'object',
  required: ['grader_ok', 'results'],
  properties: {
    grader_ok: { type: 'boolean' },
    error: { type: 'string' },
    results: { type: 'array', items: { type: 'object', required: ['id', 'category_ok', 'priority_ok'],
      properties: { id: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } } } },
  },
}
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: { type: 'array', items: { type: 'object', required: ['rid', 'tone', 'reason'],
      properties: { rid: { type: 'string' }, tone: { type: 'number' }, reason: { type: 'string' } } } },
  },
}
const FA_SCHEMA = {
  type: 'object',
  required: ['types'],
  properties: {
    types: { type: 'array', items: { type: 'object',
      required: ['name', 'kind', 'what', 'how_to_spot', 'trial_ids', 'fix', 'grader_bug_suspected'],
      properties: {
        name: { type: 'string' },
        kind: { type: 'string', enum: ['agent', 'prompt', 'tool', 'grader', 'judge', 'harness'] },
        what: { type: 'string' },
        how_to_spot: { type: 'string' },
        trial_ids: { type: 'array', items: { type: 'string' } },
        fix: { type: 'string' },
        grader_bug_suspected: { type: 'boolean' },
      } } },
  },
}
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'object', required: ['gap', 'effect'],
      properties: { gap: { type: 'string' }, effect: { type: 'string' } } } },
  },
}

// ---------- Trials ----------
const trials = []
const haltReasons = []

function trialPrompt(cell) {
  return [
    'You run one trial of the triage agent. Your only job is to run one command and report its output.',
    '',
    `Command: ${TRIAGE_CMD} --config ${cell.config.file} --ticket ${TICKET_DIR}/${cell.ticket}.json --json`,
    '',
    'Rules:',
    `- You may read only the command output, the triage/ folder, and ${TICKET_DIR}/.`,
    `- Do not open, list, search, or print anything under ${FORBIDDEN}. Do not look for answer keys, graders, plans, or predictions.`,
    '- Do not edit any file. Do not change the command. Run it once. Run it a second time only if the first run hit a rate limit.',
    '- Copy label.category, label.priority, reply, tool_calls, tool_errors, usage, and latency_ms from the command JSON exactly. Do not judge or fix the answer.',
    '- In files_read, list every path you opened or listed, including through shell commands.',
    '- Set status to "rate_limited" if the API refused for rate limits, "harness_error" if the command failed for any other reason, and "ok" otherwise.',
  ].join('\n')
}

async function runTrial(cell, n, phaseName) {
  const id = `${TAG}-${cell.config.id}-${cell.ticket}-t${n}`
  if (!reserve(EST_TRIAL_USD, id)) return null
  const t0 = Date.now()
  let r
  try {
    r = await agent(trialPrompt(cell), { label: id, phase: phaseName, schema: TRIAL_SCHEMA, model: 'opus' })
  } catch (e) {
    r = { status: 'harness_error', error: String(e?.message ?? e) }
  }
  settle(EST_TRIAL_USD, r?.cost_usd)
  const rec = {
    id, cell: cell.key, config: cell.config.id, ticket: cell.ticket, n,
    topUp: phaseName === 'Top-up', wall_ms: Date.now() - t0,
    ...r, voided: false, void_reason: null,
  }
  const peek = (rec.files_read ?? []).find(p => String(p).includes(FORBIDDEN))
  if (peek) {
    rec.voided = true
    rec.void_reason = `self-reported read of ${peek}`
  }
  trials.push(rec)
  return rec
}

async function scanTranscripts(recs, label) {
  if (!recs.length) return null
  if (!TRANSCRIPT_DIR) {
    log('No args.transcriptDir. The peek check uses self-reported files_read only.')
    return null
  }
  if (!reserve(EST_AGENT_USD, label)) return null
  const r = await agent([
    `Scan the subagent transcripts in ${TRANSCRIPT_DIR} for the trial labels listed below.`,
    `Report every label whose transcript shows a read, list, search, or print of any path under ${FORBIDDEN}.`,
    'Look at tool calls and command text. Ignore the trial prompt itself, which names that folder only to forbid it.',
    'Do not change any file. Set scanned to the number of listed labels you found a transcript for.',
    '', 'Labels:', ...recs.map(t => t.id),
  ].join('\n'), { label, phase: 'Scan', schema: SCAN_SCHEMA, model: 'opus' })
  settle(EST_AGENT_USD)
  const byId = new Map(recs.map(t => [t.id, t]))
  for (const p of r.peeked) {
    const t = byId.get(p.id)
    if (t) {
      t.voided = true
      t.void_reason = `transcript: ${p.evidence}`
    }
  }
  if (r.scanned < recs.length) log(`Transcript scan found ${r.scanned} of ${recs.length} transcripts.`)
  return r
}

function checkVoids() {
  for (const c of CONFIGS) {
    const mine = trials.filter(t => t.config === c.id)
    const v = mine.filter(t => t.voided).length
    if (mine.length && v / mine.length > VOID_HALT_RATE) {
      haltReasons.push(`${c.id}: ${v} of ${mine.length} trials read ${FORBIDDEN}. Treat as a leaked answer key.`)
    }
  }
}

// ---------- Grade (code first) ----------
const gradable = t => t.status === 'ok' && !t.voided

async function gradeAll(recs, part, phaseName) {
  const todo = recs.filter(gradable)
  const batches = []
  for (let i = 0; i < todo.length; i += GRADE_BATCH) batches.push(todo.slice(i, i + GRADE_BATCH))
  await inChunks(batches.map((b, i) => ({ b, i })), async ({ b, i }) => {
    const label = `${TAG}-grade-${part}-${i + 1}`
    if (!reserve(EST_GRADE_USD, label)) {
      for (const t of b) t.ungraded = true
      return
    }
    const file = `spe/evals/runs/${TAG}/${part}-${i + 1}.jsonl`
    const rows = b.map(t => JSON.stringify({ id: t.id, ticket: t.ticket, label: { category: t.category, priority: t.priority } }))
    const r = await agent([
      `Write the ${rows.length} lines below to ${file}, one JSON object per line, exactly as given.`,
      `Then run: python spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --input ${file} --json`,
      'Return the grader result for every row. Copy the booleans from the grader output. Do not compute them yourself.',
      'Do not edit grade.py, answers.json, or the rows. If the grader exits nonzero or skips a row, set grader_ok to false and put the error text in error.',
      '', ...rows,
    ].join('\n'), { label, phase: phaseName, schema: GRADE_SCHEMA, model: 'opus' })
    settle(EST_GRADE_USD)
    if (!r.grader_ok) {
      throw new Error(`Grader failed on ${label}: ${r.error ?? 'no error text'}. Halting. A broken grader halts the round.`)
    }
    const byId = new Map(r.results.map(x => [x.id, x]))
    for (const t of b) {
      const g = byId.get(t.id)
      if (!g) {
        t.ungraded = true
        continue
      }
      t.category_ok = g.category_ok
      t.priority_ok = g.priority_ok
      t.pass = g.category_ok && g.priority_ok
    }
  })
}

// ---------- Judge (only what code cannot check) ----------
async function judgeAll(recs) {
  const todo = recs.filter(t => gradable(t) && t.reply)
  await inChunks([...groupBy(todo, t => t.ticket).entries()], async ([ticket, group]) => {
    const label = `${TAG}-judge-${ticket}`
    if (!reserve(EST_JUDGE_USD, label)) return
    const order = shuffle(group, label)
    const byRid = new Map(order.map((t, i) => [`R${i + 1}`, t]))
    const r = await agent([
      'You judge the tone of first replies to one support ticket.',
      `Read the rubric at spe/evals/graders/judge.md and the ticket at ${TICKET_DIR}/${ticket}.json.`,
      'Score each reply on the rubric scale. Judge tone only. Do not judge the category or the priority.',
      'The replies come from different agent setups in random order. Do not guess which setup wrote which reply.',
      'Return one score for every reply id.',
      '', ...order.map((t, i) => `### R${i + 1}\n${t.reply}`),
    ].join('\n'), { label, phase: 'Judge', schema: JUDGE_SCHEMA, model: 'opus' })
    settle(EST_JUDGE_USD)
    for (const s of r.scores) {
      const t = byRid.get(s.rid)
      if (t) {
        t.tone = s.tone
        t.tone_reason = s.reason
      }
    }
  })
}

// ---------- Run ----------
phase('Trials')
log(`${TAG}: ${cells.length} cells x ${TRIALS} trials. Cap $${CAP_USD}. Max ${MAX_AGENTS} agents. Dry run: ${Boolean(ONLY)}.`)
const base = cells.flatMap(cell => Array.from({ length: TRIALS }, (_, i) => ({ cell, n: i + 1 })))
await inChunks(base, ({ cell, n }) => runTrial(cell, n, 'Trials'))

phase('Scan')
const scanBase = await scanTranscripts([...trials], `${TAG}-scan-base`)
checkVoids()
if (haltReasons.length) {
  log(`HALT: ${haltReasons.join(' ')}`)
  return { round: ROUND, tag: TAG, halted: true, haltReasons, spent_usd: r3(spent), agents_used: agentsUsed,
    voided: trials.filter(t => t.voided).map(t => ({ id: t.id, reason: t.void_reason })) }
}

phase('Grade')
await gradeAll([...trials], 'base', 'Grade')

phase('Top-up')
const splitCells = [...groupBy(trials.filter(t => t.pass !== undefined), t => t.cell).entries()]
  .filter(([, ts]) => ts.some(t => t.pass) && ts.some(t => !t.pass))
  .map(([key]) => cells.find(c => c.key === key))
const extra = splitCells
  .flatMap(cell => Array.from({ length: TOPUP_PER_CELL }, (_, k) => ({ cell, n: TRIALS + k + 1 })))
  .sort((a, b) => a.n - b.n || a.cell.key.localeCompare(b.cell.key))
for (const x of extra.slice(TOPUP_MAX)) skip(`${TAG}-${x.cell.key}-t${x.n}`, 'top-up cap', 0)
const before = trials.length
await inChunks(extra.slice(0, TOPUP_MAX), ({ cell, n }) => runTrial(cell, n, 'Top-up'))
const added = trials.slice(before)
const scanTopUp = await scanTranscripts(added, `${TAG}-scan-topup`)
checkVoids()
await gradeAll(added, 'topup', 'Top-up')
log(`Top-up: ${splitCells.length} split cells. ${added.length} extra trials run.`)

phase('Judge')
await judgeAll(trials)

phase('Synthesis')
function metricsFor(recs) {
  const done = recs.filter(t => t.status === 'ok' && !t.voided)
  const g = done.filter(t => t.pass !== undefined)
  const j = done.filter(t => typeof t.tone === 'number')
  return {
    trials_started: recs.length,
    completed: done.length,
    harness_errors: recs.filter(t => t.status === 'harness_error').length,
    rate_limited: recs.filter(t => t.status === 'rate_limited').length,
    voided: recs.filter(t => t.voided).length,
    graded: g.length,
    ungraded: done.filter(t => t.ungraded).length,
    judged: j.length,
    category_acc: r3(mean(g.map(t => (t.category_ok ? 1 : 0)))),
    priority_acc: r3(mean(g.map(t => (t.priority_ok ? 1 : 0)))),
    both_acc: r3(mean(g.map(t => (t.pass ? 1 : 0)))),
    tone_mean: r3(mean(j.map(t => t.tone))),
    mean_tool_calls: r3(mean(done.map(t => t.tool_calls))),
    mean_tool_errors: r3(mean(done.map(t => t.tool_errors))),
    mean_tokens: r3(mean(done.map(t => t.input_tokens + t.output_tokens))),
    mean_latency_ms: r3(mean(done.map(t => t.latency_ms))),
    reported_cost_usd: r3(done.reduce((s, t) => s + (t.cost_usd || 0), 0)),
  }
}
// Headline numbers use base trials only, since the prediction is for TRIALS per cell.
const metrics = {}
for (const c of CONFIGS) {
  const mine = trials.filter(t => t.config === c.id)
  metrics[c.id] = { base: metricsFor(mine.filter(t => !t.topUp)), with_top_up: metricsFor(mine) }
}

const failed = trials
  .filter(t => gradable(t) && (t.pass === false || (typeof t.tone === 'number' && t.tone <= TONE_FAIL)))
  .slice(0, 120)
  .map(t => ({ id: t.id, config: t.config, ticket: t.ticket, category: t.category, priority: t.priority,
    category_ok: t.category_ok, priority_ok: t.priority_ok, tone: t.tone ?? null, tone_reason: t.tone_reason ?? null,
    tool_errors: t.tool_errors, reply: (t.reply ?? '').slice(0, 400) }))

let failureTypes = null
if (failed.length && reserve(EST_AGENT_USD, `${TAG}-failure-analysis`, true)) {
  failureTypes = await agent([
    'Group the failed triage trials below into failure types. Name each type plainly.',
    `You may read spe/evals/tasks/answers.json for the expected labels and ${TICKET_DIR}/ for the tickets.`,
    'Do not read spe/predictions/ or spe/plans/.',
    'If a reference label looks wrong, or the grader marks a right answer wrong, that is a grader failure. Set grader_bug_suspected to true and say why.',
    'Split differences between configs into separate types when the cause differs.',
    '', JSON.stringify(failed, null, 2),
  ].join('\n'), { label: `${TAG}-failure-analysis`, phase: 'Synthesis', schema: FA_SCHEMA, model: 'opus' })
  settle(EST_AGENT_USD)
}

const summary = {
  round: ROUND, tag: TAG, dry_run: Boolean(ONLY), cells: cells.length, metrics,
  split_cells: splitCells.map(c => c.key), top_up_run: added.length,
  transcript_scan: { base: scanBase?.scanned ?? 'not run', top_up: scanTopUp?.scanned ?? 'not run' },
  skips: skips.length, spent_usd: r3(spent), cap_usd: CAP_USD, agents_used: agentsUsed,
  failure_types: failureTypes?.types?.map(t => ({ name: t.name, kind: t.kind, count: t.trial_ids.length })) ?? [],
}

let critic = null
if (reserve(EST_AGENT_USD, `${TAG}-critic`, true)) {
  critic = await agent([
    'You are the completeness critic for this eval run. Check the run against the approved plan and list every gap.',
    'Plan:',
    `- Configs: ${CONFIGS.map(c => `${c.id} (${c.note})`).join(', ')}.`,
    `- ${EXPECTED_TICKETS} tickets, ${TRIALS} trials per cell, ${CONFIGS.length * EXPECTED_TICKETS * TRIALS} base trials.`,
    '- Code grader spe/evals/graders/grade.py on label.category and label.priority against spe/evals/tasks/answers.json.',
    '- Opus tone judge using spe/evals/graders/judge.md, blind to config.',
    `- Spend cap $${CAP_USD}. Top-up up to ${TOPUP_PER_CELL} per split cell and ${TOPUP_MAX} in total.`,
    `- Trials must not read ${FORBIDDEN}. Trials that peeked are voided.`,
    '',
    'Check for missing cells, completed trials that were not graded or judged, cap skips, voids, harness errors, rate limits, whether the transcript scan ran, the judge model family, and anything that makes a number unfit to compare with a prediction.',
    'Do not read spe/predictions/.',
    '', 'Run summary:', JSON.stringify(summary, null, 2),
  ].join('\n'), { label: `${TAG}-critic`, phase: 'Synthesis', schema: CRITIC_SCHEMA, model: 'opus' })
  settle(EST_AGENT_USD)
}

log(`${TAG} done. Spent about $${spent.toFixed(2)} of $${CAP_USD}. ${skips.length} skips. ${trials.filter(t => t.voided).length} voided.`)

return {
  ...summary,
  halted: haltReasons.length > 0,
  haltReasons,
  skips,
  voided: trials.filter(t => t.voided).map(t => ({ id: t.id, reason: t.void_reason })),
  failure_types: failureTypes?.types ?? [],
  critic,
  notes: [
    'The judge is Opus, which is in the same model family as the Sonnet triage configs. This harness has no judge from a different family.',
    'Spend counts each call as max(estimate, reported cost). Estimates are unmeasured.',
    'Headline metrics use base trials only. The with_top_up metrics include the extra trials on split cells.',
  ],
  trials: trials.map(t => ({ id: t.id, cell: t.cell, n: t.n, topUp: t.topUp, status: t.status, voided: t.voided,
    category: t.category, priority: t.priority, category_ok: t.category_ok, priority_ok: t.priority_ok,
    pass: t.pass, tone: t.tone ?? null, tool_calls: t.tool_calls, tool_errors: t.tool_errors,
    tokens: (t.input_tokens ?? 0) + (t.output_tokens ?? 0), latency_ms: t.latency_ms, cost_usd: t.cost_usd })),
}
```
